pair A, B, C, D;

A = dir(45);
B = dir(45 + 90);
C = dir(45 + 180);
D = dir(45 + 270);

draw(Circle((0,0),1));
draw((-1.2,0)--(1.2,0));
draw((0,-1.2)--(0,1.2));

dot("$a$", A, A);
dot("$b$", B, B);
dot("$c$", C, C);
dot("$d$", D, D);
[/asy]
